:root {
  --ink: #04070a;
  --bone: #ded6c3;
  --bone-dim: #a99f8c;
  --gold: #c9a86a;
  --gold-bright: #f3d28b;
  --blood: #8f1f24;
  --teal: #16343a;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #020405;
  color: var(--bone);
  font-family: "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
}

#app { position: absolute; inset: 0; overflow: hidden; }
#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}

/* ── Atmosphere layers ────────────────────────────────────── */
#grain {
  position: absolute; inset: -50%;
  pointer-events: none; z-index: 4; opacity: .16;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='160' height='160' filter='url(%23n)' opacity='.7'/></svg>");
  animation: grainShift .55s steps(3) infinite;
  mix-blend-mode: overlay;
}
@keyframes grainShift {
  0% { transform: translate(0, 0); }
  33% { transform: translate(-2%, 1.5%); }
  66% { transform: translate(1.5%, -2%); }
  100% { transform: translate(0, 0); }
}
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 5;
  background: radial-gradient(ellipse at 50% 48%, transparent 38%, rgba(0,0,0,.38) 76%, rgba(0,0,0,.82) 100%);
}
#danger-vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 6; opacity: 0;
  background: radial-gradient(ellipse at 50% 50%, transparent 40%, rgba(88,4,6,.45) 85%, rgba(42,0,2,.8) 100%);
  transition: opacity .25s ease;
}
#lightning-flash {
  position: absolute; inset: 0; pointer-events: none; z-index: 7; opacity: 0;
  background: #cfe5ff;
  mix-blend-mode: screen;
}
#lightning-flash.flash { animation: lightning .65s ease-out; }
@keyframes lightning {
  0% { opacity: 0; } 4% { opacity: .55; } 10% { opacity: .05; }
  18% { opacity: .38; } 30% { opacity: 0; } 100% { opacity: 0; }
}
#damage-flash {
  position: absolute; inset: 0; pointer-events: none; z-index: 20; opacity: 0;
  background: radial-gradient(circle, rgba(120,0,0,.15), rgba(60,0,0,.92));
}

.hidden { display: none !important; }

/* ── Generic buttons / screens ────────────────────────────── */
.screen { position: absolute; inset: 0; z-index: 30; }
.ritual-btn {
  position: relative;
  appearance: none; border: 1px solid rgba(201,168,106,.65);
  background: linear-gradient(180deg, rgba(40,30,17,.75), rgba(8,7,5,.9));
  color: var(--gold-bright);
  font-family: inherit;
  font-size: clamp(12px, 1.5vw, 15px);
  letter-spacing: .34em;
  padding: 16px 30px 15px;
  cursor: pointer;
  clip-path: polygon(9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%, 0 9px);
  transition: background .25s, color .25s, box-shadow .25s;
}
.ritual-btn::before, .ritual-btn::after {
  content: "✦"; position: absolute; top: 50%; transform: translateY(-50%);
  font-size: 9px; color: var(--gold); opacity: .7;
}
.ritual-btn::before { left: 11px; }
.ritual-btn::after { right: 11px; }
.ritual-btn:hover, .ritual-btn:active {
  background: linear-gradient(180deg, rgba(87,62,28,.85), rgba(20,13,6,.94));
  color: #fff3d2;
  box-shadow: 0 0 34px rgba(201,168,106,.23), inset 0 0 24px rgba(201,168,106,.1);
}
.ghost-btn {
  appearance: none; background: none; border: 0; color: var(--bone-dim);
  font-family: inherit; letter-spacing: .22em; font-size: 11px;
  padding: 10px 18px; cursor: pointer; margin-top: 8px;
}
.ghost-btn:hover { color: var(--gold); }

/* ── Boot ─────────────────────────────────────────────────── */
#boot {
  position: absolute; inset: 0; z-index: 90; background: #020405;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 26px; transition: opacity .8s ease;
}
#boot.done { opacity: 0; pointer-events: none; }
#boot p { margin: 0; font-size: 10px; letter-spacing: .42em; color: #7d7464; }
.boot-candle { width: 10px; height: 44px; background: linear-gradient(#d6c9a8, #6f644f); position: relative; border-radius: 2px; }
.boot-candle i {
  position: absolute; left: 50%; top: -18px; width: 13px; height: 20px;
  transform: translateX(-50%);
  background: radial-gradient(circle at 50% 70%, #fff7c7 0 16%, #f3b13c 36%, rgba(196,74,14,.7) 58%, transparent 72%);
  border-radius: 50% 50% 46% 46%;
  animation: flame 1.1s ease-in-out infinite alternate;
  filter: drop-shadow(0 0 12px rgba(240,160,58,.85));
}
@keyframes flame {
  0% { transform: translateX(-50%) scale(.92) rotate(-2deg); opacity: .85; }
  100% { transform: translateX(-50%) scale(1.08) rotate(2deg); opacity: 1; }
}

/* ── Title ────────────────────────────────────────────────── */
#title-screen {
  background:
    radial-gradient(ellipse at 50% 35%, rgba(4,10,12,.08) 0%, rgba(2,5,7,.42) 45%, rgba(1,2,3,.88) 100%),
    linear-gradient(180deg, rgba(2,5,7,.5) 0%, rgba(2,4,5,.22) 48%, rgba(1,2,3,.78) 100%);
  display: flex; align-items: center; justify-content: center;
  overflow: hidden;
}
.title-fog {
  position: absolute; width: 140%; height: 60%; pointer-events: none;
  background: radial-gradient(ellipse at 50% 50%, rgba(120,153,156,.16), transparent 65%);
  filter: blur(28px); mix-blend-mode: screen;
}
.fog-a { bottom: -24%; left: -20%; animation: fogDrift 19s ease-in-out infinite alternate; }
.fog-b { top: 6%; right: -30%; height: 42%; opacity: .6; animation: fogDrift 26s ease-in-out infinite alternate-reverse; }
@keyframes fogDrift {
  0% { transform: translate(-4%, 1%) scale(1); }
  100% { transform: translate(6%, -3%) scale(1.12); }
}
.title-content {
  position: relative; z-index: 2; text-align: center;
  padding: 24px max(20px, 6vw);
  animation: titleIn 2s ease both;
}
@keyframes titleIn { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
.eyebrow {
  margin: 0 0 6px; color: var(--gold); font-size: 10px; letter-spacing: .62em;
  text-indent: .62em; opacity: .85;
}
.title-content h1 {
  margin: 0; font-weight: 400; line-height: .82;
  font-size: clamp(54px, 11.5vw, 142px);
  letter-spacing: .035em;
  color: #ddd5c2;
  text-shadow: 0 0 42px rgba(173,201,200,.14), 0 4px 0 rgba(0,0,0,.6);
}
.title-content h1 span {
  color: #8b2528;
  text-shadow: 0 0 34px rgba(143,31,36,.35), 0 0 90px rgba(80,10,14,.35);
  letter-spacing: .13em;
}
.korean {
  margin: 18px 0 0; font-size: clamp(11px, 1.5vw, 14px); letter-spacing: .58em;
  color: #8f8878; text-indent: .58em;
}
.ornament { display: flex; align-items: center; justify-content: center; gap: 12px; margin: 22px auto 16px; width: min(320px, 70vw); }
.ornament i { height: 1px; flex: 1; background: linear-gradient(90deg, transparent, rgba(201,168,106,.55), transparent); }
.ornament b { color: var(--gold); font-size: 10px; font-weight: 400; }
.tagline {
  margin: 0 auto; color: #bdb5a4; font-size: clamp(13px, 1.7vw, 17px);
  line-height: 1.75; letter-spacing: .04em; font-style: italic;
}
.tagline em { color: #a44949; font-style: normal; }
.title-content .ritual-btn { margin-top: 28px; min-width: 240px; }
.headphones { margin: 18px 0 0; color: #6d675a; font-size: 9px; letter-spacing: .34em; }
.control-legend {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 8px 22px;
  margin: 26px auto 0; max-width: 620px; color: #716b5e; font-size: 9px; letter-spacing: .14em;
}
.control-legend span { white-space: nowrap; }
.control-legend b { color: #a89a7a; font-weight: 400; margin-right: 4px; letter-spacing: .2em; }
.title-foot {
  position: absolute; bottom: calc(16px + var(--safe-b)); left: 0; right: 0; margin: 0;
  text-align: center; color: #514d45; font-size: 8px; letter-spacing: .26em;
  padding: 0 16px;
}

/* ── Intro ────────────────────────────────────────────────── */
#intro-overlay {
  z-index: 28; pointer-events: none;
  background: radial-gradient(ellipse at center, rgba(2,5,7,.2), rgba(2,4,5,.78));
  display: flex; align-items: center; justify-content: center;
  transition: opacity 1.6s ease;
}
#intro-overlay.fade { opacity: 0; }
.intro-box { text-align: center; max-width: 620px; padding: 30px 24px; animation: titleIn 1.6s ease both; }
.intro-kicker { font-size: 9px; letter-spacing: .5em; color: var(--gold); margin: 0 0 18px; }
.intro-box h2 {
  font-size: clamp(24px, 4.2vw, 46px); font-weight: 400; line-height: 1.25;
  margin: 0 0 18px; color: #ded6c4; text-shadow: 0 2px 20px rgba(0,0,0,.8);
}
.intro-box p { color: #a9a08e; font-size: clamp(12px, 1.5vw, 15px); line-height: 1.9; margin: 0; }
.intro-box em { color: #8c3f42; font-style: italic; }
.intro-controls { margin-top: 24px !important; color: #736c5e !important; font-size: 10px !important; letter-spacing: .16em; }

/* ── HUD ──────────────────────────────────────────────────── */
#hud { position: absolute; inset: 0; z-index: 12; pointer-events: none; }
#top-hud { position: absolute; top: calc(12px + var(--safe-t)); left: calc(14px + var(--safe-l)); right: calc(14px + var(--safe-r)); display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
#objective-panel { min-width: 0; max-width: 34vw; }
.hud-label { margin: 0 0 4px; font-size: 8px; letter-spacing: .45em; color: #8d372f; }
#objective-text { margin: 0; font-size: clamp(10px, 1.25vw, 13px); line-height: 1.45; letter-spacing: .06em; color: #c8c0ad; text-shadow: 0 1px 8px #000; }
#relic-panel { display: flex; gap: 7px; padding-top: 2px; }
.relic-slot {
  width: clamp(27px, 4.2vw, 36px); height: clamp(34px, 5.2vw, 44px);
  border: 1px solid rgba(201,168,106,.25);
  background: rgba(5,8,9,.45);
  display: flex; align-items: center; justify-content: center;
  clip-path: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px);
  transition: border-color .5s, box-shadow .5s;
}
.relic-slot span { color: rgba(201,168,106,.16); font-size: 15px; transition: color .6s, text-shadow .6s; }
.relic-slot.lit { border-color: rgba(243,210,139,.75); box-shadow: 0 0 18px rgba(201,168,106,.22), inset 0 0 14px rgba(201,168,106,.1); }
.relic-slot.lit span { color: var(--gold-bright); text-shadow: 0 0 10px rgba(255,217,139,.9), 0 0 24px rgba(243,165,75,.55); }

#compass {
  position: relative; width: 96px; height: 84px; flex: 0 0 auto;
  display: flex; flex-direction: column; align-items: center; justify-content: flex-start;
  opacity: .9;
}
.compass-ring {
  position: absolute; top: 0; width: 64px; height: 64px; border-radius: 50%;
  border: 1px solid rgba(201,168,106,.2);
  background: radial-gradient(circle, rgba(6,11,12,.18), rgba(3,6,7,.46));
  box-shadow: inset 0 0 20px rgba(0,0,0,.6);
}
.compass-ring::before, .compass-ring::after {
  content: ""; position: absolute; left: 50%; width: 1px; height: 5px; background: rgba(201,168,106,.4);
}
.compass-ring::before { top: -1px; }
.compass-ring::after { bottom: -1px; }
#compass-arrow {
  position: absolute; top: 10px; left: 50%; width: 0; height: 0; margin-left: -5px;
  transform-origin: 5px 22px;
  border-left: 5px solid transparent; border-right: 5px solid transparent;
  border-bottom: 13px solid #c9a86a;
  filter: drop-shadow(0 0 5px rgba(243,210,139,.55));
  will-change: transform;
}
.compass-dot {
  position: absolute; top: 31px; left: 50%; width: 3px; height: 3px; margin: -1.5px 0 0 -1.5px;
  border-radius: 50%; background: #594f3d;
}
#compass-label { position: absolute; top: 66px; font-size: 7px; letter-spacing: .24em; color: #8d8169; }
#compass-dist { position: absolute; top: 75px; font-size: 10px; letter-spacing: .1em; color: #c9b78e; }

#room-toast {
  position: absolute; top: 24%; left: 50%; transform: translateX(-50%);
  font-size: clamp(13px, 2vw, 19px); letter-spacing: .5em; text-indent: .5em;
  color: #cfc5ae; text-shadow: 0 0 18px rgba(0,0,0,.95), 0 2px 10px #000;
  opacity: 0; transition: opacity 1.2s ease; white-space: nowrap; pointer-events: none;
}
#room-toast.show { opacity: .85; }

#subtitle {
  position: absolute; left: 50%; bottom: 25%; transform: translateX(-50%);
  max-width: min(600px, 82vw); text-align: center;
  font-size: clamp(11px, 1.5vw, 15px); font-style: italic; line-height: 1.6;
  color: #cfc7b7; text-shadow: 0 1px 6px #000, 0 0 18px #000;
  opacity: 0; transition: opacity .8s ease; pointer-events: none;
}
#subtitle.show { opacity: .95; }

#crosshair {
  position: absolute; top: 50%; left: 50%; width: 26px; height: 26px;
  transform: translate(-50%, -50%); opacity: .5; transition: opacity .3s;
}
#crosshair i { position: absolute; background: rgba(222,214,195,.55); }
#crosshair i:nth-child(1) { left: 12px; top: 0; width: 1px; height: 7px; }
#crosshair i:nth-child(2) { left: 12px; bottom: 0; width: 1px; height: 7px; }
#crosshair i:nth-child(3) { top: 12px; left: 0; height: 1px; width: 7px; }
#crosshair i:nth-child(4) { top: 12px; right: 0; height: 1px; width: 7px; }
#crosshair b { position: absolute; left: 12px; top: 12px; width: 2px; height: 2px; margin: -1px 0 0 -1px; border-radius: 50%; background: rgba(222,214,195,.75); }
#crosshair.active { opacity: 1; }
#crosshair.active b { background: var(--gold-bright); box-shadow: 0 0 8px var(--gold-bright); }

#interact-prompt {
  position: absolute; left: 50%; bottom: calc(27% + 4px); transform: translateX(-50%);
  display: flex; align-items: center; gap: 9px;
  padding: 7px 16px 7px 12px; border: 1px solid rgba(201,168,106,.24);
  background: rgba(3,6,7,.7); backdrop-filter: blur(3px);
  font-size: 10px; letter-spacing: .18em; color: #ded4bc; white-space: nowrap;
  transition: opacity .2s;
}
#interact-prompt .key {
  width: 19px; height: 19px; border: 1px solid rgba(201,168,106,.5); border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--gold-bright); font-size: 9px;
}

#stamina-wrap {
  position: absolute; left: calc(174px + var(--safe-l)); bottom: calc(34px + var(--safe-b));
  width: 86px; height: 3px; background: rgba(255,255,255,.08); opacity: .8;
}
#stamina-bar { height: 100%; width: 100%; background: linear-gradient(90deg, #66542f, #c9a86a); transition: width .1s linear; }
#stamina-wrap span { position: absolute; top: 8px; left: 0; font-size: 6px; letter-spacing: .3em; color: #6d6454; }

#pause-btn {
  position: absolute; top: calc(12px + var(--safe-t)); left: 50%; transform: translateX(-50%);
  pointer-events: auto; display: none;
}

.icon-btn {
  appearance: none; width: 34px; height: 34px; border-radius: 50%;
  border: 1px solid rgba(201,168,106,.24); background: rgba(3,6,7,.55);
  color: #b7ac93; font-size: 12px; cursor: pointer;
}
.icon-btn:active { background: rgba(201,168,106,.15); }

/* ── Touch controls ───────────────────────────────────────── */
#touch-controls { position: absolute; inset: 0; pointer-events: none; }
#joystick-zone {
  position: absolute; left: calc(22px + var(--safe-l)); bottom: calc(24px + var(--safe-b));
  width: 132px; height: 156px; pointer-events: auto;
}
#joystick-base {
  position: absolute; bottom: 0; left: 0;
  width: 118px; height: 118px; border-radius: 50%;
  border: 1px solid rgba(201,168,106,.22);
  background: radial-gradient(circle, rgba(25,34,34,.34), rgba(3,7,8,.4));
  box-shadow: inset 0 0 26px rgba(0,0,0,.45);
  touch-action: none;
}
#joystick-base::before, #joystick-base::after {
  content: ""; position: absolute; left: 50%; top: 50%; background: rgba(201,168,106,.14);
  transform: translate(-50%,-50%);
}
#joystick-base::before { width: 1px; height: 76%; }
#joystick-base::after { height: 1px; width: 76%; }
#joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px;
  border-radius: 50%; border: 1px solid rgba(224,203,157,.5);
  background: radial-gradient(circle at 36% 30%, rgba(195,170,118,.36), rgba(14,19,19,.78));
  box-shadow: 0 0 18px rgba(0,0,0,.4), inset 0 0 12px rgba(201,168,106,.08);
  will-change: transform;
}
#sprint-btn {
  position: absolute; right: 0; top: 0; width: 50px; height: 50px;
  font-size: 8px; letter-spacing: .14em;
}
#sprint-btn.on { border-color: rgba(243,210,139,.8); color: #f3d28b; box-shadow: 0 0 16px rgba(201,168,106,.25); }

#action-cluster {
  position: absolute; right: calc(20px + var(--safe-r)); bottom: calc(24px + var(--safe-b));
  display: flex; align-items: flex-end; gap: 14px; pointer-events: auto;
}
.round-btn {
  appearance: none; border-radius: 50%; border: 1px solid rgba(201,168,106,.32);
  background: radial-gradient(circle at 38% 32%, rgba(44,55,52,.55), rgba(4,8,9,.68));
  color: #c7bda7; font-family: inherit;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;
  backdrop-filter: blur(2px); cursor: pointer; touch-action: none;
}
.round-btn small { font-size: 6px; letter-spacing: .2em; color: #7f7561; }
.round-btn.small { width: 54px; height: 54px; font-size: 18px; }
.round-btn.use { width: 76px; height: 76px; font-size: 24px; border-color: rgba(201,168,106,.52); }
.round-btn.use:active, .round-btn.small:active, .round-btn.on {
  background: radial-gradient(circle, rgba(93,71,36,.6), rgba(9,12,11,.72));
  color: #f6dda6; box-shadow: 0 0 22px rgba(201,168,106,.2), inset 0 0 14px rgba(201,168,106,.12);
}
.round-btn.use.pulse { animation: usePulse 1.6s ease-in-out infinite; }
@keyframes usePulse {
  0%,100% { box-shadow: 0 0 0 rgba(201,168,106,0); border-color: rgba(201,168,106,.3); }
  50% { box-shadow: 0 0 24px rgba(201,168,106,.28); border-color: rgba(243,210,139,.8); }
}

/* ── Hiding ───────────────────────────────────────────────── */
#hide-overlay {
  position: absolute; inset: 0; z-index: 10; opacity: 0; pointer-events: none;
  transition: opacity .45s ease;
  background: linear-gradient(180deg, rgba(0,0,0,.97), rgba(2,3,3,.86) 22%, rgba(2,3,3,.6) 50%, rgba(0,0,0,.9) 100%);
}
#hide-overlay.show { opacity: 1; }
#hide-overlay .slats {
  position: absolute; inset: 0;
  background: repeating-linear-gradient(180deg, transparent 0 22px, rgba(0,0,0,.88) 22px 36px);
  mask-image: radial-gradient(ellipse 34% 50% at 50% 46%, #000 22%, transparent 72%);
  -webkit-mask-image: radial-gradient(ellipse 34% 50% at 50% 46%, #000 22%, transparent 72%);
}
#hide-overlay p {
  position: absolute; left: 50%; bottom: 17%; transform: translateX(-50%);
  margin: 0; white-space: nowrap; color: #8b816c; font-size: 9px; letter-spacing: .28em;
}
#hide-overlay p b { color: #c9a86a; font-weight: 400; }

/* ── Pause / End modals ───────────────────────────────────── */
#pause-screen, #end-screen {
  background: radial-gradient(ellipse at 50% 40%, rgba(6,11,12,.72), rgba(1,3,4,.95));
  display: flex; align-items: center; justify-content: center; padding: 20px;
  backdrop-filter: blur(4px);
}
.modal-box {
  text-align: center; width: min(520px, 92vw);
  padding: clamp(26px, 5vw, 46px) clamp(20px, 5vw, 44px);
  border: 1px solid rgba(201,168,106,.16);
  background: linear-gradient(180deg, rgba(8,12,13,.9), rgba(3,5,6,.95));
  clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px);
  box-shadow: 0 20px 80px rgba(0,0,0,.7);
  animation: titleIn .7s ease both;
}
.modal-kicker { margin: 0 0 12px; color: #8d372f; font-size: 8px; letter-spacing: .5em; }
.modal-box h2 {
  margin: 0 0 18px; font-weight: 400; font-size: clamp(30px, 6vw, 58px);
  letter-spacing: .08em; color: #ded6c3; line-height: 1;
}
.modal-copy { margin: 0 auto 24px; max-width: 370px; color: #a09a8b; font-size: clamp(11px, 1.5vw, 14px); line-height: 1.8; font-style: italic; }
.modal-copy em { color: #96545a; }
#end-screen .modal-box h2 { color: #a43a3a; text-shadow: 0 0 40px rgba(143,31,36,.35); }
#end-screen.win .modal-box h2 { color: #d7bd86; text-shadow: 0 0 44px rgba(201,168,106,.28); }
#end-screen.win .modal-kicker { color: #8f7b52; }
.end-stats { display: flex; justify-content: center; gap: 26px; margin: 0 0 24px; flex-wrap: wrap; }
.end-stats div { text-align: center; }
.end-stats b { display: block; font-weight: 400; font-size: 22px; color: #c9b78e; letter-spacing: .08em; }
.end-stats span { font-size: 7px; letter-spacing: .28em; color: #6d6454; }
.end-quote { margin: 20px 0 0; color: #6e6759; font-size: 10px; font-style: italic; letter-spacing: .08em; }

/* ── Jumpscare ────────────────────────────────────────────── */
#jumpscare {
  position: absolute; inset: 0; z-index: 80; display: none; overflow: hidden;
  background: #000;
}
#jumpscare.show { display: block; animation: scareShake .09s linear infinite; }
@keyframes scareShake {
  0% { transform: translate(0,0); } 25% { transform: translate(-7px,4px); }
  50% { transform: translate(6px,-5px); } 75% { transform: translate(-4px,-3px); }
  100% { transform: translate(5px,6px); }
}
.scare-hair {
  position: absolute; left: 50%; top: 46%; width: 74vmin; height: 92vmin;
  transform: translate(-50%,-50%);
  background: radial-gradient(ellipse at 50% 40%, #0a0a0b 0 42%, #020202 66%, transparent 72%);
  filter: blur(5px);
}
.scare-face {
  position: absolute; left: 50%; top: 46%; width: 46vmin; height: 62vmin;
  transform: translate(-50%,-50%); border-radius: 46% 46% 42% 42% / 38% 38% 56% 56%;
  background:
    radial-gradient(ellipse at 38% 20%, rgba(255,255,255,.28), transparent 30%),
    radial-gradient(ellipse at 50% 48%, #d8d5c6 0%, #a8a999 46%, #5d625c 72%, #242927 100%);
  box-shadow: 0 0 12vmin rgba(160,180,170,.12), inset 0 0 8vmin rgba(0,0,0,.35);
  animation: faceLunge .72s cubic-bezier(.18,.9,.35,1) both;
}
@keyframes faceLunge {
  0% { transform: translate(-50%,-50%) scale(.55); filter: brightness(.3) contrast(1.4); }
  55% { transform: translate(-50%,-50%) scale(1.16); filter: brightness(1.1) contrast(1.2); }
  100% { transform: translate(-50%,-50%) scale(1); filter: brightness(.92) contrast(1.35); }
}
.scare-eyes { position: absolute; top: 31%; left: 0; width: 100%; display: flex; justify-content: space-evenly; }
.scare-eyes i {
  display: block; width: 9vmin; height: 11vmin; border-radius: 50%;
  background: radial-gradient(circle at 50% 46%, #ff3b2f 0 8%, #6b0602 22%, #050202 46%, #000 72%);
  box-shadow: 0 0 4vmin rgba(255,34,20,.55);
  animation: eyeTremble .08s steps(2) infinite alternate;
}
@keyframes eyeTremble { from { transform: translateX(-1px) scale(1.02); } to { transform: translateX(1px) scale(1); } }
.scare-brow {
  position: absolute; top: 24%; left: 12%; width: 76%; height: 3%;
  background: radial-gradient(ellipse at 50% 50%, rgba(12,12,12,.55), transparent 70%);
  filter: blur(4px);
}
.scare-nose {
  position: absolute; top: 45%; left: 50%; width: 3.4vmin; height: 8vmin;
  transform: translateX(-50%); border-radius: 50%;
  background: radial-gradient(ellipse at 50% 40%, rgba(40,44,40,.4), transparent 70%);
}
.scare-mouth {
  position: absolute; top: 58%; left: 50%; width: 19vmin; height: 27vmin;
  transform: translateX(-50%);
  border-radius: 46% 46% 50% 50% / 26% 26% 72% 72%;
  background: radial-gradient(ellipse at 50% 70%, #260306 0 18%, #080202 48%, #000 70%);
  box-shadow: 0 0 4vmin rgba(90,0,0,.5), inset 0 0 3vmin #000;
  animation: mouthStretch .5s ease-in-out infinite alternate;
}
@keyframes mouthStretch { from { transform: translateX(-50%) scaleY(.94) scaleX(.97); } to { transform: translateX(-50%) scaleY(1.06) scaleX(1.03); } }
.scare-vignette {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 50%, transparent 24%, rgba(60,0,0,.46) 62%, #000 92%);
  mix-blend-mode: multiply;
}

/* ── Rotate hint ──────────────────────────────────────────── */
#rotate-hint {
  position: absolute; left: 50%; top: calc(62px + var(--safe-t)); transform: translateX(-50%);
  z-index: 15; padding: 7px 13px; background: rgba(3,6,7,.65);
  border: 1px solid rgba(201,168,106,.18);
  color: #8d8169; font-size: 8px; letter-spacing: .2em; white-space: nowrap;
  pointer-events: none;
}

/* ── Responsive ───────────────────────────────────────────── */
@media (max-width: 640px) {
  #objective-panel { max-width: 42vw; }
  #compass { width: 80px; transform: scale(.9); transform-origin: top center; }
  #stamina-wrap { left: calc(158px + var(--safe-l)); bottom: calc(30px + var(--safe-b)); width: 66px; }
  .round-btn.small { width: 48px; height: 48px; }
  .round-btn.use { width: 68px; height: 68px; }
  #action-cluster { gap: 9px; right: calc(14px + var(--safe-r)); }
  #joystick-zone { left: calc(12px + var(--safe-l)); width: 118px; height: 140px; }
  #joystick-base { width: 106px; height: 106px; }
  #interact-prompt { bottom: 30%; }
  .control-legend { display: none; }
  .title-content h1 { font-size: clamp(52px, 17vw, 90px); }
}

@media (min-width: 900px) {
  #touch-controls { display: none; }
  #stamina-wrap { left: calc(20px + var(--safe-l)); bottom: calc(24px + var(--safe-b)); width: 120px; }
  #interact-prompt { bottom: 19%; }
  #subtitle { bottom: 22%; }
  #pause-btn { display: block; }
}

@media (orientation: portrait) and (max-width: 900px) {
  #subtitle { bottom: 29%; }
  #interact-prompt { bottom: 35%; }
}

@media (max-height: 520px) {
  .title-content h1 { font-size: clamp(40px, 13vh, 74px); }
  .title-content .ritual-btn { margin-top: 16px; padding: 12px 26px; }
  .headphones, .title-foot, .ornament { display: none; }
  .tagline { font-size: 12px; line-height: 1.5; }
  #room-toast { top: 20%; }
  #subtitle { bottom: 30%; }
  .modal-box { padding: 18px 28px; }
  .modal-box h2 { font-size: 32px; margin-bottom: 10px; }
  .modal-copy { margin-bottom: 14px; }
}

@media (prefers-reduced-motion: reduce) {
  #grain { animation: none; }
  .fog-a, .fog-b { animation: none; }
}

import * as THREE from '../vendor/three.module.js';

function canvas(size) {
  const c = document.createElement('canvas');
  c.width = size;
  c.height = size;
  return c;
}

function finish(c, repeatX = 1, repeatY = 1, srgb = true) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = THREE.RepeatWrapping;
  t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeatX, repeatY);
  t.anisotropy = 4;
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

function noise(ctx, size, amount = 16, alpha = 0.16) {
  const img = ctx.getImageData(0, 0, size, size);
  const d = img.data;
  for (let i = 0; i < d.length; i += 4) {
    const n = (Math.random() - 0.5) * amount;
    d[i] = Math.max(0, Math.min(255, d[i] + n));
    d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + n));
    d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + n));
  }
  ctx.putImageData(img, 0, 0);
  // soft grime blooms
  for (let k = 0; k < 26; k++) {
    const x = Math.random() * size, y = Math.random() * size;
    const r = 24 + Math.random() * 90;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(4,7,6,${alpha * Math.random()})`);
    g.addColorStop(1, 'rgba(4,7,6,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }
}

export function wallpaperTexture() {
  const size = 512;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#334644';
  ctx.fillRect(0, 0, size, size);

  // vertical tone bands
  const band = ctx.createLinearGradient(0, 0, size, 0);
  for (let i = 0; i <= 10; i++) {
    band.addColorStop(i / 10, i % 2 ? '#2c3e3c' : '#384c49');
  }
  ctx.globalAlpha = 0.65;
  ctx.fillStyle = band;
  ctx.fillRect(0, 0, size, size);
  ctx.globalAlpha = 1;

  // pinstripes
  ctx.strokeStyle = 'rgba(150,165,150,.08)';
  ctx.lineWidth = 2;
  for (let x = 16; x < size; x += 64) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, size);
    ctx.stroke();
  }

  // damask motifs
  const drawDamask = (cx, cy, s) => {
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(s / 100, s / 100);
    ctx.strokeStyle = 'rgba(157,175,158,.17)';
    ctx.fillStyle = 'rgba(157,175,158,.055)';
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(0, -46);
    ctx.bezierCurveTo(20, -30, 22, -8, 0, 0);
    ctx.bezierCurveTo(-22, -8, -20, -30, 0, -46);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(28, 16, 32, 38, 0, 48);
    ctx.bezierCurveTo(-32, 38, -28, 16, 0, 0);
    ctx.fill();
    ctx.stroke();
    // leaf curls
    ctx.lineWidth = 1.8;
    for (const dir of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(dir * 4, -14);
      ctx.bezierCurveTo(dir * 34, -24, dir * 40, 2, dir * 22, 12);
      ctx.bezierCurveTo(dir * 32, 4, dir * 28, -10, dir * 10, -9);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(dir * 3, 15);
      ctx.bezierCurveTo(dir * 30, 26, dir * 34, 42, dir * 14, 42);
      ctx.stroke();
    }
    ctx.restore();
  };

  for (let y = 0; y < 3; y++) {
    for (let x = 0; x < 2; x++) {
      drawDamask(128 + x * 256, 86 + y * 170, 105);
      drawDamask(256 + x * 256 - 128, 172 + y * 170, 46);
    }
  }

  noise(ctx, size, 14, 0.24);

  // darker toward edges
  const edge = ctx.createRadialGradient(size / 2, size / 2, size * 0.25, size / 2, size / 2, size * 0.72);
  edge.addColorStop(0, 'rgba(0,0,0,0)');
  edge.addColorStop(1, 'rgba(0,0,0,.28)');
  ctx.fillStyle = edge;
  ctx.fillRect(0, 0, size, size);

  return finish(c, 1, 1);
}

export function woodTexture() {
  const size = 512;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#2b1d13';
  ctx.fillRect(0, 0, size, size);
  const plankH = 64;
  for (let row = 0; row < size / plankH; row++) {
    const offset = (row % 2) * 120;
    for (let px = -1; px < 3; px++) {
      const x = px * 256 + offset;
      const shade = 26 + Math.random() * 22;
      ctx.fillStyle = `rgb(${shade + 18},${shade + 4},${Math.max(10, shade - 10)})`;
      ctx.fillRect(x, row * plankH, 256, plankH - 2);
      // grain
      for (let g = 0; g < 18; g++) {
        ctx.strokeStyle = `rgba(${10 + Math.random() * 30},${8 + Math.random() * 18},${4 + Math.random() * 10},${0.1 + Math.random() * 0.25})`;
        ctx.lineWidth = 0.7 + Math.random() * 1.6;
        const gy = row * plankH + 4 + Math.random() * (plankH - 8);
        ctx.beginPath();
        ctx.moveTo(x + 3, gy);
        ctx.bezierCurveTo(x + 80, gy + (Math.random() - 0.5) * 7, x + 170, gy + (Math.random() - 0.5) * 8, x + 253, gy + (Math.random() - 0.5) * 4);
        ctx.stroke();
      }
      // seam
      ctx.fillStyle = 'rgba(3,2,1,.65)';
      ctx.fillRect(x + 254, row * plankH, 3, plankH);
      // nails
      ctx.fillStyle = 'rgba(10,8,6,.8)';
      ctx.beginPath(); ctx.arc(x + 12, row * plankH + 12, 1.8, 0, 7); ctx.fill();
      ctx.beginPath(); ctx.arc(x + 243, row * plankH + plankH - 12, 1.8, 0, 7); ctx.fill();
    }
    ctx.fillStyle = 'rgba(0,0,0,.55)';
    ctx.fillRect(0, row * plankH + plankH - 2, size, 2);
  }
  noise(ctx, size, 10, 0.28);
  return finish(c, 1, 1);
}

export function darkWoodTexture() {
  const size = 256;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#24170f';
  ctx.fillRect(0, 0, size, size);
  for (let i = 0; i < 70; i++) {
    ctx.strokeStyle = `rgba(${8 + Math.random() * 24},${5 + Math.random() * 14},${2 + Math.random() * 8},${0.18 + Math.random() * 0.3})`;
    ctx.lineWidth = 0.6 + Math.random() * 2.2;
    const y = Math.random() * size;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.bezierCurveTo(size * 0.3, y + (Math.random() - 0.5) * 14, size * 0.7, y + (Math.random() - 0.5) * 14, size, y + (Math.random() - 0.5) * 6);
    ctx.stroke();
  }
  noise(ctx, size, 8, 0.3);
  return finish(c, 1, 1);
}

export function stoneTexture() {
  const size = 512;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#232a2b';
  ctx.fillRect(0, 0, size, size);
  const rowH = 74;
  for (let row = 0; row < 8; row++) {
    const offset = (row % 2) * 62;
    for (let col = -1; col < 6; col++) {
      const x = col * 124 + offset;
      const y = row * rowH;
      const g = 30 + Math.random() * 18;
      ctx.fillStyle = `rgb(${g},${g + 4},${g + 5})`;
      ctx.fillRect(x + 3, y + 3, 118, rowH - 6);
      ctx.fillStyle = 'rgba(0,0,0,.35)';
      ctx.fillRect(x + 3, y + rowH - 4, 118, 4);
    }
  }
  noise(ctx, size, 18, 0.3);
  return finish(c, 1, 1);
}

export function plasterTexture() {
  const size = 512;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#262b28';
  ctx.fillRect(0, 0, size, size);
  noise(ctx, size, 20, 0.36);
  // cracks
  ctx.strokeStyle = 'rgba(5,7,6,.55)';
  for (let k = 0; k < 5; k++) {
    let x = Math.random() * size, y = Math.random() * size;
    ctx.lineWidth = 0.8 + Math.random() * 1.4;
    ctx.beginPath();
    ctx.moveTo(x, y);
    for (let s = 0; s < 9; s++) {
      x += (Math.random() - 0.5) * 48;
      y += Math.random() * 34;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  // water stains
  for (let k = 0; k < 7; k++) {
    const x = Math.random() * size, y = Math.random() * size, r = 30 + Math.random() * 100;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(45,38,24,.28)');
    g.addColorStop(1, 'rgba(45,38,24,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
  }
  return finish(c, 1, 1);
}

export function rugTexture(variant = 0) {
  const size = 512;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const base = variant === 1 ? '#2b1716' : '#3a1a18';
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, size, size);
  ctx.strokeStyle = 'rgba(168,134,78,.42)';
  ctx.lineWidth = 9;
  ctx.strokeRect(18, 18, size - 36, size - 36);
  ctx.strokeStyle = 'rgba(168,134,78,.2)';
  ctx.lineWidth = 2;
  ctx.strokeRect(36, 36, size - 72, size - 72);
  ctx.strokeRect(56, 56, size - 112, size - 112);

  // border motifs
  ctx.fillStyle = 'rgba(168,134,78,.22)';
  for (let i = 0; i < 24; i++) {
    const t = i / 24;
    const x1 = 46 + t * (size - 92), y1 = 46;
    const x2 = 46 + t * (size - 92), y2 = size - 46;
    ctx.save(); ctx.translate(x1, y1); ctx.rotate(Math.PI / 4); ctx.fillRect(-3, -3, 6, 6); ctx.restore();
    ctx.save(); ctx.translate(x2, y2); ctx.rotate(Math.PI / 4); ctx.fillRect(-3, -3, 6, 6); ctx.restore();
    ctx.save(); ctx.translate(x1, y2); ctx.rotate(Math.PI / 4); ctx.fillRect(-3, -3, 6, 6); ctx.restore();
    ctx.save(); ctx.translate(x2, y1); ctx.rotate(Math.PI / 4); ctx.fillRect(-3, -3, 6, 6); ctx.restore();
  }

  // central medallion
  ctx.save();
  ctx.translate(size / 2, size / 2);
  ctx.strokeStyle = 'rgba(168,134,78,.35)';
  ctx.lineWidth = 3;
  for (let r = 8; r < 158; r += 26) {
    ctx.beginPath();
    if (r % 52 === 8) {
      for (let a = 0; a < 16; a++) {
        const rr = r + (a % 2 ? 12 : 0);
        const ang = (a / 16) * Math.PI * 2;
        const px = Math.cos(ang) * rr, py = Math.sin(ang) * rr;
        a === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
      }
      ctx.closePath();
    } else {
      ctx.arc(0, 0, r, 0, Math.PI * 2);
    }
    ctx.stroke();
  }
  ctx.restore();

  noise(ctx, size, 18, 0.32);
  // worn patches
  for (let i = 0; i < 10; i++) {
    const x = Math.random() * size, y = Math.random() * size, r = 10 + Math.random() * 50;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(15,8,7,.25)');
    g.addColorStop(1, 'rgba(15,8,7,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(x, y, r, 0, 7); ctx.fill();
  }
  return finish(c, 1, 1);
}

export function portraitTexture(variant = 0) {
  const w = 256, h = 384;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  const bg = ctx.createLinearGradient(0, 0, 0, h);
  bg.addColorStop(0, variant ? '#1d1712' : '#171d1c');
  bg.addColorStop(1, '#080807');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);

  // halo
  const halo = ctx.createRadialGradient(w / 2, 150, 10, w / 2, 150, 130);
  halo.addColorStop(0, 'rgba(185,178,155,.16)');
  halo.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, w, h);

  ctx.fillStyle = '#0b0b0a';
  // shoulders
  ctx.beginPath();
  ctx.ellipse(w / 2, h - 30, 118, 138, 0, Math.PI, Math.PI * 2);
  ctx.fill();
  // neck
  ctx.fillRect(w / 2 - 20, 238, 40, 60);
  // face
  ctx.fillStyle = variant ? 'rgba(190,174,146,.78)' : 'rgba(168,178,164,.72)';
  ctx.beginPath();
  ctx.ellipse(w / 2, 185, 50, 72, 0, 0, Math.PI * 2);
  ctx.fill();
  // hair
  ctx.fillStyle = '#0a0a09';
  ctx.beginPath();
  ctx.ellipse(w / 2, 150, 60, 62, 0, Math.PI, Math.PI * 2);
  ctx.fill();
  ctx.fillRect(w / 2 - 58, 150, 17, 118);
  ctx.fillRect(w / 2 + 41, 150, 17, 118);
  // eyes
  ctx.fillStyle = variant ? '#2b0d0d' : '#0c1412';
  ctx.beginPath(); ctx.ellipse(w / 2 - 20, 176, 7, 4, 0, 0, 7); ctx.fill();
  ctx.beginPath(); ctx.ellipse(w / 2 + 20, 176, 7, 4, 0, 0, 7); ctx.fill();
  ctx.fillStyle = 'rgba(220,205,170,.55)';
  ctx.beginPath(); ctx.arc(w / 2 - 20, 176, 1.5, 0, 7); ctx.fill();
  ctx.beginPath(); ctx.arc(w / 2 + 20, 176, 1.5, 0, 7); ctx.fill();
  // mouth
  ctx.strokeStyle = 'rgba(50,20,20,.6)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(w / 2, 214, 12, 0.15 * Math.PI, 0.85 * Math.PI);
  ctx.stroke();

  // craquelure
  ctx.strokeStyle = 'rgba(0,0,0,.35)';
  for (let i = 0; i < 22; i++) {
    ctx.lineWidth = 0.5 + Math.random();
    let x = Math.random() * w, y = Math.random() * h;
    ctx.beginPath(); ctx.moveTo(x, y);
    for (let s = 0; s < 4; s++) {
      x += (Math.random() - 0.5) * 28; y += (Math.random() - 0.5) * 28;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  // vignette
  const vg = ctx.createRadialGradient(w / 2, h / 2, 40, w / 2, h / 2, 220);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,.65)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, w, h);
  return finish(c, 1, 1);
}

export function glowTexture(color = '#ffd28a') {
  const size = 128;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,0.95)');
  g.addColorStop(0.16, color);
  g.addColorStop(0.45, 'rgba(120,90,30,.28)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function dustTexture() {
  const size = 64;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, 'rgba(255,248,225,.85)');
  g.addColorStop(0.35, 'rgba(255,248,225,.22)');
  g.addColorStop(1, 'rgba(255,248,225,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function stainedGlassTexture() {
  const size = 256;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#0a0d0d';
  ctx.fillRect(0, 0, size, size);
  const cols = ['#4f7291', '#7c3f46', '#9b8346', '#3e655d', '#4b4a7a'];
  const cols2 = ['#1b3148', '#451f26', '#4e3d1c', '#1e3833', '#282647'];
  for (let gy = 0; gy < 6; gy++) {
    for (let gx = 0; gx < 4; gx++) {
      ctx.fillStyle = Math.random() > 0.4 ? cols[(gx + gy) % 5] : cols2[(gx * 2 + gy) % 5];
      ctx.globalAlpha = 0.6 + Math.random() * 0.3;
      ctx.beginPath();
      ctx.roundRect(gx * 64 + 4, gy * 42 + 4, 56, 34, 4);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
  ctx.strokeStyle = 'rgba(5,7,7,.9)';
  ctx.lineWidth = 4;
  for (let gy = 0; gy <= 6; gy++) {
    ctx.beginPath(); ctx.moveTo(0, gy * 42); ctx.lineTo(size, gy * 42); ctx.stroke();
  }
  for (let gx = 0; gx <= 4; gx++) {
    ctx.beginPath(); ctx.moveTo(gx * 64, 0); ctx.lineTo(gx * 64, size); ctx.stroke();
  }
  return finish(c, 1, 1);
}

export function moonTexture() {
  const size = 256;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(128, 128, 10, 128, 128, 128);
  g.addColorStop(0, 'rgba(225,235,220,1)');
  g.addColorStop(0.12, 'rgba(210,224,210,.9)');
  g.addColorStop(0.26, 'rgba(175,195,190,.32)');
  g.addColorStop(1, 'rgba(120,150,160,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

import * as THREE from '../vendor/three.module.js';
import {
  wallpaperTexture, woodTexture, darkWoodTexture, stoneTexture, plasterTexture,
  rugTexture, portraitTexture, glowTexture, stainedGlassTexture, moonTexture, dustTexture
} from './textures.js';

export const WALL_HEIGHT = 3.5;

const ROOM_DEFS = [
  { id: 'library', name: 'THE LIBRARY', minX: -16, maxX: -4, minZ: -14, maxZ: -4 },
  { id: 'chapel', name: 'THE CHAPEL', minX: -4, maxX: 4, minZ: -14, maxZ: -4 },
