    const plaster = plasterTexture();
    plaster.repeat.set(5, 5);
    const ceiling = new THREE.MeshStandardMaterial({ map: plaster, roughness: 1, color: 0x76736b });

    const darkWoodMap = darkWoodTexture();
    darkWoodMap.repeat.set(2, 2);

    const wax = new THREE.MeshStandardMaterial({ color: 0xd6c8a2, roughness: 0.8, emissive: 0x2a1e0a, emissiveIntensity: 0.35 });
    const flame = new THREE.MeshBasicMaterial({ color: 0xffcf7c, toneMapped: false });
    const fire = new THREE.MeshBasicMaterial({ color: 0xff7a22, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });
    const doorInset = new THREE.MeshStandardMaterial({ color: 0x2b1b10, roughness: 0.75 });
    const paper = new THREE.MeshStandardMaterial({ color: 0xc8bea2, roughness: 0.9 });
    const sofaMat = new THREE.MeshStandardMaterial({ color: 0x3e2926, roughness: 0.96 });
    const sofaLight = new THREE.MeshStandardMaterial({ color: 0x53352f, roughness: 0.96 });
    const altarCloth = new THREE.MeshStandardMaterial({ color: 0x4c171b, roughness: 0.92, emissive: 0x170406, emissiveIntensity: 0.4 });
    const books = [0x5b2528, 0x2d4038, 0x4d4227, 0x30324a, 0x5b4a2b, 0x3a2522].map(c =>
      new THREE.MeshStandardMaterial({ color: c, roughness: 0.9 }));
    const rugMap = rugTexture(0);
    const rug2Map = rugTexture(1);

    return {
      wallpaper, wood, stone, kitchenFloor, stoneFloor, ceiling,
      darkWood: new THREE.MeshStandardMaterial({ map: darkWoodMap, color: 0x8a7660, roughness: 0.78 }),
      wainscot: new THREE.MeshStandardMaterial({ map: darkWoodMap.clone(), color: 0x5a4736, roughness: 0.8 }),
