      map: getGlowTexture(spec.color), transparent: true, opacity: spec.op,
      blending: THREE.AdditiveBlending, depthWrite: false, color: 0xffffff
    });
    const s = new THREE.Sprite(m);
    s.position.y = spec.y;
    s.scale.set(spec.sx, spec.sy, 1);
